# --- 5. BACKGROUND ENGINE ---
$BgImg = Get-ImageFromBase64 $Base64Background
$Form.Add_Paint({
    $g = $_.Graphics
    $rect = $Form.ClientRectangle
    if ($BgImg -ne $null) { $g.DrawImage($BgImg, $rect) } else { $g.Clear([System.Drawing.Color]::Black) }
    $brushDim = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(100, 0, 0, 0)) 
    $g.FillRectangle($brushDim, $rect)
    $penBorder = New-Object System.Drawing.Pen([System.Drawing.ColorTranslator]::FromHtml($Color_Neon), 2)
    $g.DrawRectangle($penBorder, 0, 0, $Form.Width-1, $Form.Height-1)
})
$Form.Add_MouseDown({
    if ($_.Button -eq [System.Windows.Forms.MouseButtons]::Left) {
        $Form.Capture = $false
        [System.Windows.Forms.Message]::Create($Form.Handle, 0xA1, 2, 0) | ForEach-Object { 
            [Type]::GetType("System.Windows.Forms.NativeWindow").GetMethod("DefWndProc", [System.Reflection.BindingFlags]"NonPublic,Instance").Invoke($Form, @($_)) 
        }
    }
})

