function Add-Toggle ($Text, $Tag, $Y) {
    $btn = New-Object System.Windows.Forms.Button
    $btn.Text = "[ ACTIVE ]  $Text"
    $btn.Name = $Tag
    $btn.Tag = @{ State="ON"; Label=$Text } 
    $btn.Font = New-Object System.Drawing.Font("Consolas", 10, [System.Drawing.FontStyle]::Bold)
    $btn.ForeColor = $Color_Neon
    $btn.FlatStyle = "Flat"
    $btn.FlatAppearance.BorderSize = 0
    $btn.FlatAppearance.MouseOverBackColor = "#40ffffff"
    $btn.FlatAppearance.MouseDownBackColor = "#80000000"
    $btn.BackColor = "Transparent"
    $btn.TextAlign = "MiddleLeft"
    $btn.Location = New-Object System.Drawing.Point(10, $Y)
    $btn.Size = New-Object System.Drawing.Size(420, 40)
    $btn.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btn.Add_Click({
        $data = $this.Tag 
        if ($data.State -eq "ON") {
            $data.State = "OFF"
            $this.ForeColor = "#888888" 
            $this.Text = "[        ]  $($data.Label)"
        } else {
            $data.State = "ON"
            $this.ForeColor = "#00f7ff" 
            $this.Text = "[ ACTIVE ]  $($data.Label)"
        }
    }) 
    $pnlGlassLeft.Controls.Add($btn)
    return $btn
}

