# --- 11. LOGIC ---
function Log ($Msg) {
    $lblLog.Text += "`n> $Msg"
    $lblLog.Refresh()
    [System.Windows.Forms.Application]::DoEvents() 
}

$Form.Add_Load({
    $Drive = Get-Volume -DriveLetter C
    $Total = [math]::Round($Drive.Size / 1GB, 1)
    $Free = [math]::Round($Drive.SizeRemaining / 1GB, 1)
    $Used = $Total - $Free
    $Form.Tag = $Free 
    $lblDiskText.Text = "CURRENT STATUS  |  FREE: $Free GB  |  USED: $Used GB  |  TOTAL: $Total GB"
    if ($Free -lt 20) { $lblDiskText.ForeColor = "#ff3333" }
})

$btnRun.Add_Click({
    $btnRun.Enabled = $false
    $lblLog.Text = "STARTING SILENT OPERATIONS..."
    $progressBar.Value = 0
    
    $BackupRoot = "C:\TGS_Safety_Bin"
    $CurrentBackup = "$BackupRoot\$(Get-Date -Format 'yyyy-MM-dd_HH-mm')"
    if (-not (Test-Path $BackupRoot)) { New-Item -ItemType Directory -Path $BackupRoot | Out-Null }
    New-Item -ItemType Directory -Path $CurrentBackup | Out-Null
    
    function Safe-Clean ($Path, $Name) {
        if (Test-Path $Path) {
            $Dest = "$CurrentBackup\$Name"
            if (-not (Test-Path $Dest)) { New-Item -ItemType Directory -Path $Dest | Out-Null }
            Get-ChildItem -Path $Path -Recurse -ErrorAction SilentlyContinue | Move-Item -Destination $Dest -Force -ErrorAction SilentlyContinue
            Log "MOVED $Name TO BIN"
        }
    }
    function Is-On ($Btn) { return $Btn.Tag.State -eq "ON" }

    # --- EXECUTION ---
    
    # STEP 1: UPDATES (15%)
    if (Is-On $togUpd) {
        Log "CLEARING UPDATES..."
        Stop-Service wuauserv -Force -ErrorAction SilentlyContinue
        Safe-Clean "C:\Windows\SoftwareDistribution\Download" "UpdateCache"
        Start-Service wuauserv
    }
    $progressBar.Value = 15

    # STEP 2: TEMP & EXTENDED LOGS (Replacing Native Disk Cleanup) (40%)
    if (Is-On $togTmp) {
        Log "PURGING TEMP & CACHES..."
        Safe-Clean "C:\Windows\Temp" "SysTemp"
        Safe-Clean "$env:TEMP" "UserTemp"
        
        # New: Clean Prefetch (Safe)
        Log "CLEANING PREFETCH..."
        Get-ChildItem "C:\Windows\Prefetch" -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne "Layout.ini" } | Remove-Item -Force -ErrorAction SilentlyContinue
        
        # New: Clean Error Reports (WER)
        Log "CLEANING ERROR REPORTS..."
        Remove-Item "C:\ProgramData\Microsoft\Windows\WER\*" -Recurse -Force -ErrorAction SilentlyContinue
        
        # New: Clean DirectX Shader Cache
        Log "CLEANING SHADER CACHE..."
        Remove-Item "$env:LOCALAPPDATA\D3DSCache\*" -Recurse -Force -ErrorAction SilentlyContinue
    }
    $progressBar.Value = 40

    # STEP 3: WINSXS (60%)
    if (Is-On $togSxS) {
        Log "RUNNING DISM (SILENT)..."
        # Hidden Window + NoNewWindow = Truly Silent
        Start-Process -FilePath "dism.exe" -ArgumentList "/online /Cleanup-Image /StartComponentCleanup" -Wait -WindowStyle Hidden
        Log "WINSXS OPTIMIZED."
    }
    $progressBar.Value = 60

    # STEP 4: BIN & DNS (80%)
    if (Is-On $togBin) {
        Log "EMPTYING RECYCLE BIN..."
        Clear-RecycleBin -Force -ErrorAction SilentlyContinue
        Log "FLUSHING DNS..."
        Clear-DnsClientCache -ErrorAction SilentlyContinue
    }
    $progressBar.Value = 80
    
    # STEP 5: VSS & BLOAT (100%)
    if (Is-On $togVSS) {
        vssadmin Resize ShadowStorage /For=C: /On=C: /MaxSize=5GB | Out-Null
        Log "VSS RESIZED."
    }

    if (Is-On $togBlo) {
         Log "SCANNING BLOATWARE..."
         $BloatList = @("*Xbox*", "*Solitaire*", "*BingWeather*", "*GetHelp*", "*FeedbackHub*", "*Zune*", "*People*", "*StickyNotes*", "*3DViewer*", "*Groove*", "*MixedReality*", "*CandyCrush*", "*Disney*", "*Spotify*", "*Netflix*")
         foreach ($App in $BloatList) {
             $Pkg = Get-AppxProvisionedPackage -Online | Where-Object { $_.DisplayName -like $App -and $_.DisplayName -notlike "*Calculator*" -and $_.DisplayName -notlike "*Store*" -and $_.DisplayName -notlike "*Photos*" }
             if ($Pkg) {
                 Remove-AppxProvisionedPackage -Online -PackageName $Pkg.PackageName -ErrorAction SilentlyContinue | Out-Null
                 Log "REMOVED: $($Pkg.DisplayName)"
             }
         }
    }
    $progressBar.Value = 100

    # FINAL
    $Drive = Get-Volume -DriveLetter C
    $EndFree = [math]::Round($Drive.SizeRemaining / 1GB, 1)
    $StartFree = $Form.Tag
    $Saved = [math]::Round(($EndFree - $StartFree), 2)
    $lblDiskText.Text = "CLEANUP COMPLETE  |  WAS: $StartFree GB  ->  NOW: $EndFree GB  |  RECLAIMED: +$Saved GB"
    $lblDiskText.ForeColor = "#00ff00"

    Log "DONE. FILES MOVED TO TGS_Safety_Bin"
    $btnRun.Text = "COMPLETED"
    $btnRun.BackColor = "#00ff00"
    $btnRun.Enabled = $true
})

